/// <summary>
/// MPJ_3173_Veera Actual sales tax amount
/// Extension of Postload and creation of new method to get the METGSTAmount(Actual sales tax amount)
/// </summary>
[ExtensionOf(tableStr(LedgerJournalEntity))]
public final class METLedgerJournalEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// Insert entity datasource method
    /// </summary>
    /// <param name = "_entityCtx">Type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Type DataEntityDataSourceRuntimeContext</param>
    /// <returns>Boolean value</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean ret = true;
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(LedgerJournalEntity, LedgerJournalTrans))
        {
            LedgerJournalTrans metLedgerJournalTrans = _dataSourceCtx.getBuffer();
            
            // Fix for intercomany LedgerDimension as the standard entity is not designed for this.
            if(metLedgerJournalTrans.AccountType   == LedgerJournalACType::Ledger && metLedgerJournalTrans.company != curExt())
            {
                RefRecId    metLedgerDimensionRecId;
                try
                {
                    changecompany(metLedgerJournalTrans.Company)
                    {
                        LedgerAccountDimensionResolver metLedgerAccountDimensionResolver = LedgerAccountDimensionResolver::newResolver(this.AccountDisplayValue);
                        metLedgerDimensionRecId = metLedgerAccountDimensionResolver.resolve();
                    }
                    if(metLedgerDimensionRecId)
                    {
                        metLedgerJournalTrans.LedgerDimension = metLedgerDimensionRecId;
                    }
                }
                catch{} // In case of failure, AccountDisplayValue gets stored in Dynamics and user has to fix it manually
            }
        }
        ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

        return ret;
    }

    /// <summary>
    /// Update entity datasource
    /// </summary>
    /// <param name = "_entityCtx">Type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Type DataEntityDataSourceRuntimeContext</param>
    /// <returns></returns>
    public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean ret;
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(LedgerJournalEntity, LedgerJournalTrans):
                LedgerJournalTrans metLedgerJournalTrans = _dataSourceCtx.getBuffer();
                
                // Fix for intercomany LedgerDimension as the standard entity is not designed for this.
                if(metLedgerJournalTrans.AccountType   == LedgerJournalACType::Ledger && metLedgerJournalTrans.company != curExt())
                {
                    RefRecId    metLedgerDimensionRecId;
                    try
                    {
                        changecompany(metLedgerJournalTrans.Company)
                        {
                            LedgerAccountDimensionResolver metLedgerAccountDimensionResolver = LedgerAccountDimensionResolver::newResolver(this.AccountDisplayValue);
                            metLedgerDimensionRecId = metLedgerAccountDimensionResolver.resolve();
                        }
                        if(metLedgerDimensionRecId)
                        {
                            metLedgerJournalTrans.LedgerDimension = metLedgerDimensionRecId;
                        }
                    }
                    catch
                    {
                    }
                    // In case of failure, AccountDisplayValue gets stored in Dynamics and user has to fix it manually
                }

                break;
        }
        ret = next updateEntityDataSource(_entityCtx, _dataSourceCtx);
        
        return ret;
    }

    /// <summary>
    /// Updates existing journal lines with any changes from staging.
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">
    /// The definition group.
    /// </param>
    /// <param name = "_dimCacheTmp">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved dynamic dimensions.
    /// </param>
    /// <param name = "_dimCacheTmpRef">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved dynamic dimensions.
    /// </param>
    /// <param name = "_defaultDimCacheTmp">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved default dimensions.
    /// </param>
    /// <param name = "_defaultDimCacheTmpRef">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved default dimensions.
    /// </param>
    /// <param name = "_delayTaxCalculation">
    /// Determines whether to delay tax calculation.
    /// </param>
    /// <returns>
    /// The number of journal lines updated.
    /// </returns>
    protected static int64 updateExistingJournalLines(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution,
        DimensionDataEntitySFKCacheTmp _dimCacheTmp,
        DimensionDataEntitySFKCacheTmp _dimCacheTmpRef,
        DimensionDataEntitySFKCacheTmp _defaultDimCacheTmp,
        DimensionDataEntitySFKCacheTmp _defaultDimCacheTmpRef,
        boolean _delayTaxCalculation)
    {

        LedgerJournalEntity::metUpdateCustomFields(_dmfDefinitionGroupExecution);

        return next updateExistingJournalLines(_dmfDefinitionGroupExecution,
                                                _dimCacheTmp,
                                                _dimCacheTmpRef,
                                                _defaultDimCacheTmp,
                                                _defaultDimCacheTmpRef,
            _delayTaxCalculation);

    }

    /// <summary>
    /// Creates new journal lines from the staging table.
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">
    /// The definition group.
    /// </param>
    /// <param name = "_dimCacheTmp">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved dynamic dimensions.
    /// </param>
    /// <param name = "_dimCacheTmpRef">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved dynamic dimensions.
    /// </param>
    /// <param name = "_defaultDimCacheTmp">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved default dimensions.
    /// </param>
    /// <param name = "_defaultDimCacheTmpRef">
    /// The <c>DimensionDataEntitySFKCacheTmp</c> instance which contains resolved default dimensions.
    /// </param>
    /// <param name = "_delayTaxCalculation">
    /// Determines whether to delay tax calculation.
    /// </param>
    /// <returns>
    /// The number of journal lines created.
    /// </returns>
    /// <remarks>
    /// Using Chain of Command, an update_recordset can be used to set extension field values for
    /// new journal lines created by this method. Typically the return value would not need to be modified.
    /// Use this pattern to copy extension fields from the source LedgerJournalEntityStaging table
    /// to the target LedgerJournalTrans table using an update_recordset statement.
    /// All update_recordset statements should contain the following where clause to restrict to
    /// the current session.
    /// update_recordset ledgerJounalTrans
    ///     setting MyLineField = staging.MyLineField
    /// join staging
    ///     where staging.JournalBatchNumber == ledgerJournalTrans.JournalNum
    ///         && staging.LineNumber == ledgerJournalTrans.LineNum
    ///         && staging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
    ///         && staging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
    ///         && staging.TransferStatus == DMFTransferStatus::NotStarted
    /// </remarks>
    protected static int64 createJournalLines(
        DMFDefinitionGroupExecution _dmfDefinitionGroupExecution,
        DimensionDataEntitySFKCacheTmp _dimCacheTmp,
        DimensionDataEntitySFKCacheTmp _dimCacheTmpRef,
        DimensionDataEntitySFKCacheTmp _defaultDimCacheTmp,
        DimensionDataEntitySFKCacheTmp _defaultDimCacheTmpRef,
        boolean _delayTaxCalculation)
    {
        
        int64   metRowCount = next createJournalLines(
                                 _dmfDefinitionGroupExecution,
                                 _dimCacheTmp,
                                 _dimCacheTmpRef,
                                 _defaultDimCacheTmp,
                                 _defaultDimCacheTmpRef,
                                 _delayTaxCalculation);
        
        LedgerJournalEntity::metUpdateCustomFields(_dmfDefinitionGroupExecution);

        return metRowCount;
    }

    /// <summary>
    /// Update custom fields if Set-based processing is set to true
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">
    /// The definition group.
    /// </param>
    private static void metUpdateCustomFields(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        LedgerJournalTrans          metLedgerJournalTrans;
        LedgerJournalEntityStaging  metStaging;

        select firstonly METCompany 
            from  metStaging
            where metStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                && metStaging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
                && (metStaging.TransferStatus == DMFTransferStatus::NotStarted
                    || metStaging.TransferStatus == DMFTransferStatus::Validated);

        if(metStaging.METCompany)
        {
            metLedgerJournalTrans.skipDataMethods(true);
            update_recordset metLedgerJournalTrans setting
                                Company     = metStaging.METCompany,
                                Payment     = metStaging.METPayment,
                                ReleaseDate = metStaging.METReleaseDate,
                                ReleaseDateComment = metStaging.METReleaseDateComment,
                                CashDiscBaseDate    = metStaging.METCashDiscBaseDate,
                                CashDiscBaseDays    = metStaging.METCashDiscBaseDays
                join metStaging
                    where metStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                        && metStaging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
                        && (metStaging.TransferStatus == DMFTransferStatus::NotStarted
                            || metStaging.TransferStatus == DMFTransferStatus::Validated)
                        && metStaging.JournalBatchNumber == metLedgerJournalTrans.JournalNum
                        && metStaging.LineNumber == metLedgerJournalTrans.LineNum;

            // Fix for intercomany LedgerDimension as the standard entity is not designed for this.
            while select forupdate metLedgerJournalTrans
                join    metStaging
                    where metStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                        && metStaging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
                        && metStaging.TransferStatus == DMFTransferStatus::NotStarted
                        && metStaging.JournalBatchNumber == metLedgerJournalTrans.JournalNum
                        && metStaging.LineNumber == metLedgerJournalTrans.LineNum
                        && metLedgerJournalTrans.AccountType   == LedgerJournalACType::Ledger 
                        && metLedgerJournalTrans.company != curExt()
            {
                RefRecId    metLedgerDimensionRecId;
                try
                {
                    changecompany(metLedgerJournalTrans.Company)
                    {
                        LedgerAccountDimensionResolver metLedgerAccountDimensionResolver = LedgerAccountDimensionResolver::newResolver(metStaging.AccountDisplayValue);
                        metLedgerDimensionRecId = metLedgerAccountDimensionResolver.resolve();
                    }
                    if(metLedgerDimensionRecId && metLedgerJournalTrans.LedgerDimension != metLedgerDimensionRecId)
                    {
                        ttsbegin;
                        metLedgerJournalTrans.LedgerDimension = metLedgerDimensionRecId;
                        metLedgerJournalTrans.doUpdate(); // Bypass update method for Set based operations
                        ttscommit;
                    }
                }
                catch
                {
                }
                // In case of failure, AccountDisplayValue gets stored in Dynamics and user has to fix it manually
            }
        }
    }

/// <summary>
/// MPJ_3173_Veera Actual sales tax amount
/// populating METGSTAmount
/// </summary>
public void postLoad()
{
    next postload();
    this.METGSTAmount = this.getMETGSTAmount();
}

    /// <summary>
    /// MPJ_2173_Veera Actual sales tax amount
    /// Calulate the actual sales tax amount
    /// </summary>
    /// <returns>Actual sales tax amount</returns>
    public TaxRegulationAmountCur getMETGSTAmount()
    {
        TaxAmount taxAmount = 0;
        
        changecompany(this.DataAreaId)
        {
            taxAmount   = Tax::taxTotalVoucherDateRecId(this.Voucher, this.TransDate, this.METLedgerJournalTransRecId);
        }

        return abs(taxAmount);
    }
